blocks.content:
1/* Import custom font */
2@import url("https://fonts.googleapis.com/css2?family=Euclid+Circular+A:wght@400;500&display=swap");
3
4* {
5    font-family: 'Euclid Circular A', sans-serif;
6    line-height: 1.5;
7}
8
9.projects-grid {
10    display: grid;
11    grid-template-columns: 2fr 1fr 1fr;
12    grid-template-rows: auto auto;
13    gap: 20px;
14}
15
16/* Style cards */
17.projects-grid > div {
18    background-color: #fff;
19    border-radius: 10px;
20    padding: 20px;
21    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
22}
23
24.primary-card {
25    grid-area: 1 / 1 / 3 / 2;
26}
27
28/* Style images */
29img {
30    width: 100%;
31    border-radius: 10px;
32}
33
34/* Style headings */
35h3 {
36    color: #25265e;
37    font-size: 1.5rem;
38    font-weight: 550;
39}
40
41/* Style paragraphs */
42p {
43    font-size: 16px;
44}
45
46/* Style links */
47a {
48    color: #0556f3;
49    font-weight: medium;
50    text-decoration: none;
51}
